    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "100.00"})).toBe(true);
    await ui.setSetting(pg_uma, "pot", "10.00");
